def calculate(a, b, operator):
    if operator == "+": return a + b
    if operator == "-": return a - b
    if operator == "*": return a * b
    if operator == "/":
        if b == 0: raise ValueError("Cannot divide by zero")
        return a / b
    raise ValueError("Unsupported operator")

print(calculate(12, 3, "*"))
